We revisit the classical problem of smooth convex optimization: solve $\min_{x \in \R^d} f(x)$ where $f$ is convex and $M$-smooth (i.e., its gradient is $M$-Lipschitz). A celebrated result is that with a prudent choice of stepsizes $\{\alpha_t\}$, the gradient descent algorithm (GD) 
\begin{align}
	x_{t+1} = x_t - \frac{\alpha_t}{M} \nabla f(x_t) 
\end{align}
solves such a convex optimization problem to arbitrary accuracy from any initialization $x_0$. How quickly does GD converge? The mainstream approach (see e.g., the textbooks \citep{BertsekasNonlinear,Nocedal,nesterov-survey,vishnoi2021algorithms,bubeck-book,BNO,lan2020first,bertsekas2015convex} among many others) is to use a constant stepsize schedule $\alpha_t \equiv \bar{\alpha} \in (0,2)$ since this ensures
\begin{align}
	f(x_n) - f^* \leq \frac{cM\|x_0 - x^*\|^2}{n} 
	\label{eq:rate-std}
\end{align}
where $x^*$ denotes any minimizer of $f$, $f^* := f(x^*)$ denotes the corresponding minimal value, and $c$ is a small constant, e.g., $c = \tfrac{1}{4}$ for $\bar{\alpha} = 1$~\citep{DT14}.


\par In this setting, the Silver Stepsize Schedule is particularly simple. For any integer $n = 2^{k}-1$, we recursively construct the schedule $h_{2n+1}$ of length $2n+1$ from the schedule $h_n$ of length $n$ via
\begin{align}
	h_{2n+1} := [h_n, \; 1 + \rho^{k-1}, \; h_n]
	\label{eq:steps-recursive}
\end{align}
where $\rho := 1 + \sqrt{2}$ denotes the silver ratio, and $h_1 := [\sqrt{2}]$. This results in the simple pattern $[\sqrt{2}, \; 2, \; \sqrt{2}, \; 1+\sqrt{2}, \dots]$ as depicted in Figure~\ref{fig:silverstepsize}. This schedule is exactly the Silver Stepsize Schedule from~\citep{alt23hedging1} in the limit that the strong convexity parameter vanishes (see Remark~\ref{rem:steps-limit} for details), and bears similarities to those in~\citep{gupta22,grimmer23,GrimmerShuWang}; see \S\ref{ssec:rel}.


We show that these stepsizes yield an improved convergence rate~\eqref{eq:rate-std} where $\tfrac{c}{n}$ is replaced by
\begin{align}
	r_k := \frac{1}{1 + \sqrt{4\rho^{2k} - 3}} \leq
	\frac{1}{2 \rho^{\log_2 n}}
	= \frac{1}{2n^{\log_2 \rho}}
	\approx \frac{1}{2 n^{1.2716}}
	\,.
	\label{eq:r-asymptotics}
\end{align}
This bound gives the correct asymptotic scaling of $r_k$ since the inequality is asymptotically tight.


\paragraph*{Indexing.} Throughout, the horizon is $n = 2^k-1$. This correspondence between $n \in \{1,3,7,15,\dots\}$ and $k \in \{1,2,3,4,\dots\}$ allows re-indexing in a way that simplifies notation for the recursion.


\paragraph*{Rescaling.} For simplicity, we normalize $M = 1$, i.e., $\| \nabla f(x) - \nabla f(y) \| \leq \|x-y\|$ for all $x,y$. This is without loss of generality since if $h$ is $M$-smooth and convex,  then $f := h/M$ is $1$-smooth and convex, thus the result we establish $f_n - f^* \leq r_k\|x_0 - x^*\|^2$ implies $h_n - h^* \leq r_k M \|x_0 - x^*\|^2$. Note that running GD on $f$ simply amounts to rescaling the Silver Stepsize Schedules for $h$ by $1/M$.


 The Silver Stepsize Schedule is defined recursively in~\eqref{eq:steps-recursive}. Here we mention an equivalent direct expression and make several remarks. Let $\bin(t)$ denote the $2$-adic valuation of $t$, i.e., the smallest non-negative integer $i$ such that $2^i$ is in the binary expansion of $t$. For example, $\bin(1) = 0$, $\bin(2) = 1$, $\bin(3) = 0$, $\bin(4) = 2$, etc.


\begin{defin}[Silver Stepsize Schedule for smooth convex optimization]
	For $t \in \{0,1, 2,\dots\}$, the $t$-th stepsize of the Silver Stepsize Schedule is
		\begin{align}
		\alpha_t
		:=
		1 + \rho^{\bin(t+1)-1}\,.
		\label{eq:steps}
	\end{align}
\end{defin}


\par Briefly, the idea behind multi-step descent is that it is essential to capture how different iterations affect other iterations' progress. We do this by exploiting long-range consistency conditions between the iterates along GD's trajectory, as encoded by the co-coercivities 
\begin{align}
	Q_{ij} := 2(f_i - f_j) + 2\langle g_j, x_j - x_i \rangle - \|g_j - g_i\|^2\,.
	\label{eq:cocoercivity}
\end{align}
The significance of these co-coercivities is that the constraints $\{Q_{ij} \geq 0\}_{i \neq j \in \{0,1,\dots,n,*\}}$ are necessary and sufficient for the existence of a $1$-smooth convex function $f$ satisfying $f_i = f(x_i)$ and $g_i = \nabla f(x_i)$ for each $i \in \{0,1,\dots,n,*\}$~\citep{pesto}. In other words, the co-coercivity conditions $\{Q_{ij} \geq 0 \}_{i \neq j \in \{0,1,\dots,n,*\}}$ generate all possible long-range consistency constraints on the objective function $f$. Or, said another way, the co-coercivity conditions generate all possible valid inequalities with which one can prove convergence rates for GD. For a further discussion, see~\citep[\S2.2]{alt23hedging1}.

\par Concretely, to prove Theorem~\ref{thm:main}, we exhibit explicit non-negative multipliers $\lam_{ij}$ satisfying
\begin{align}
	\sum_{i \neq j \in \{0, \dots, n,*\}} \lam_{ij} Q_{ij}  = 
	\|x_0 - x^*\|^2 - \|x_n - c_k g_n - x^*\|^2
	+ \frac{f^* - f_n}{r_k}\,,
	\label{eq:cert}
\end{align}
where we use the shorthand $c_k := \frac{1}{2r_k}$. Since $\sum_{ij}\lam_{ij} Q_{ij} \geq 0$ for any $1$-smooth convex function, and since $\|x_n - c_k g_n - x^*\|^2 \geq 0$ trivially as it is a square, this immediately implies the desired rate 
\begin{align}
	f_n - f^* \leq r_k \|x_0 - x^*\|^2\,.
	\label{eq:cert-cor}
\end{align}


\begin{example}[$n=1$]\label{ex:n=1}
	For $n=1$, the identity~\eqref{eq:cert} is
	\begin{align*}
		\sum_{i \neq j \in \{0, 1, *\}} \lam_{ij} Q_{ij} 
		=
		\|x_0 - x^*\|^2 - \|x_1 - c_1 g_1 - x^*\|^2 + \frac{f^* - f_1}{r_1}\,.
	\end{align*}
	Here, $x_1 = x_0 - \sqrt{2} g_0$, $r_1 
	= \frac{1}{1+\sqrt{4\rho^2-3}}
	\approx 0.1816$, $c_1 = \frac{1}{2r_1} \approx 2.7535$, and 
	\begin{align*}
		\begin{bmatrix}
			\lam_{00} & \lam_{01} & \lam_{0*} \\
			\lam_{10} & \lam_{11} & \lam_{1*} \\
			\lam_{*0} & \lam_{*1} & \lam_{**}
		\end{bmatrix}
		=
		\begin{bmatrix}
			0
			&
			1+\sqrt{2}
			&
			0
			\\
			1
			&
			0
			&
			\sqrt{2}
			\\
			\sqrt{2}
			&
			\frac{1}{2r_1}
			&
			0
		\end{bmatrix}
		\,.
	\end{align*}
\end{example}

\par For larger horizons $n$, we construct $\lam_{ij}$ via the recursive gluing technique of~\citep{alt23hedging1}. See Figure~\ref{fig:gluing}. Below, we say that the multipliers $\{\sig_{ij}\}_{i,j \in \{0,\dots,n,*\}}$ satisfy the $*$-sparsity property if $\sig_{i*} = 0$ for all $i < n$. This is satisfied by construction and simplifies part of the proof (isolated in Lemma~\ref{lem:opt}). 


The rest of the section is dedicated to proving Theorem~\ref{thm:cert}. We first isolate two helper lemmas in \S\ref{ssec:gluing:helper}, and then we combine them to prove the result in \S\ref{ssec:gluing:pf}.  For notational simplicity, henceforth we assume $x^* = 0$; this is without loss of generality after translating. 

\subsection{Helper lemmas}\label{ssec:gluing:helper}

Here we provide three helper lemmas for the proof of Theorem~\ref{thm:cert}. The first lemma explicitly computes all multipliers involving $x^*$ for the $n$-step certificate. 


The next two lemmas are more substantial. These help us verify~\eqref{eq:cert:2n+1}---which consists of a linear form in all $2n+3$ function values and a quadratic form in all $2n+3$ gradients and iterates. Na\"ively verifying such an identity requires checking $\Theta(n)$ coefficients for the linear form and $\Theta(n^2)$ coefficients for the quadratic form. The following two lemmas show that due to the recursive construction of the Silver Stepsize Schedule and the gluing, these forms only affect the indices $n,2n+1,*$. This reduces verifying the rate certificate~\eqref{eq:cert:2n+1} to checking only $\Theta(1)$ coefficients, as detailed below in \S\ref{ssec:gluing:pf}. Below, for shorthand, let $F_{ij} := 2(f_i - f_j)$ and $P_{ij} := 2\langle g_j, x_j - x_i \rangle - \|g_i - g_j\|^2$  denote the linear and quadratic components of $Q_{ij}$, respectively. For bookkeeping purposes, we use $3$-dimensional vectors and $4 \times 4$ matrices to denote the coefficients of these forms. 


The vectors $e, s, \ell$ in Lemma~\ref{lem:succinct-linear} are defined as follows:
\begin{align*}
	\small
	e := \begin{bmatrix} 
		\frac{1}{r_k} \\
		-\frac{1}{r_{k+1}} + \frac{1+2\rho}{r_k} \\
		\frac{1}{r_{k+1}} - \frac{4\rho}{r_k}
	\end{bmatrix}
	\,,
	\qquad
	s := 2\rho(\rho^{k} - 1) \begin{bmatrix}
		1 \\
		1 \\
		-2
	\end{bmatrix}
	\,,
	\qquad
	\ell := \begin{bmatrix}
		\frac{1}{r_k} - 2\rho(\rho^k - 1)\\
		-\frac{1}{r_{k+1}} + \frac{1+2\rho}{r_k} - 2\rho(\rho^k - 1) \\
		\frac{1}{r_{k+1}} - \frac{4\rho}{r_k} + 4\rho(\rho^k - 1)
	\end{bmatrix}\,.
\end{align*}


The matrices in Lemma~\ref{lem:succinct} are defined as follows. For brevity, we write $\sim$ for the entries below the diagonal since these coefficient matrices are symmetric.
\begin{align*}
	\small
	E :=
	\begin{bmatrix}
		-2\rho
		&
		(1 + 2\rho) (1 + \rho^{k-1}) -\frac{1}{2r_k} 
		&
		0
		&
		0
		\\
		\sim
		&
		\frac{1}{4r_k^2} - (1 + 2\rho) (1+\rho^{k-1})^2
		&
		0
		&
		0 
		\\
		\sim
		&
		\sim
		&
		2\rho 
		&
		\frac{1}{2r_{k+1}} - \frac{1+2\rho}{2r_k}
		\\
		\sim & \sim & \sim &
		\frac{1+2\rho}{4r_k^2} - \frac{1}{4r_{k+1}^2}
	\end{bmatrix}
\end{align*}
\begin{align*}
	\small
	S := 
	\begin{bmatrix}
		0
		&
		\Delta_{2n+1,n} + \Delta_{*,n}
		&
		0
		&
		-\Delta_{n,2n+1}
		\\
		\sim
		&
		-\left( \Delta_{n,*} + \Delta_{*,n} + \Delta_{2n+1,n} + \Delta_{n,2n+1} \right)
		&
		-\Delta_{2n+1,n}
		&
		\Delta_{n,2n+1} + \Delta_{2n+1,n}
		\\
		\sim
		&
		\sim
		&
		0
		&
		\Delta_{n,2n+1} + \Delta_{*,2n+1}
		\\
		\sim
		&
		\sim
		&
		\sim
		&
		- \left( \Delta_{n,2n+1} + \Delta_{2n+1,n}  + \Delta_{2n+1,*} + \Delta_{*,2n+1}\right)
	\end{bmatrix}
\end{align*}
\begin{align*}
	\small
	L :=  \rho \begin{bmatrix}
		-2
		&
		2 + \rho^{k-1} 
		&
		0
		&
		1
		\\
		\sim
		&
		-1 - \rho^k - 2 \rho^{k-1} 
		&
		\rho^{k-1}
		&
		- 1 - \rho^{k-1}
		\\
		\sim
		&
		\sim
		&
		2
		&
		-1
		\\
		\sim
		&
		\sim
		&
		\sim
		&
		1 - \rho^k
	\end{bmatrix}
\end{align*}

