\begin{theorem}[Main result]\label{thm:main}
	For any horizon $n = 2^k - 1$, any dimension $d$, any $M$-smooth convex function $f : \R^d \to \R$, and any initialization $x_0 \in \R^d$, 
	\begin{align}
		f(x_n) - f^* \leq r_k\, M\|x_0 - x^*\|^2 \,,
	\end{align}
	where $x^*$ denotes any minimizer of $f$, and $x_n$ denotes the output of $n$ steps of GD using the Silver Stepsize Schedule. In particular, in order to achieve error $f(x_n) - f^* \leq \eps$, it suffices to run GD for
	\begin{align*}
		n
		\leq
		\left( \frac{M \|x_0 - x^*\|^2}{2 \eps} \right)^{\log_{\rho} 2} 
		\approx
		\left( \frac{M\|x_0 - x^*\|2}{2 \eps} \right)^{0.7864}
		\;\; \text{iterations}.
	\end{align*}
\end{theorem}

