			\Delta_{*,n}
			&
			\Delta_{*,2n+1} 
			&
			\Delta_{*,*}
		\end{bmatrix}
		:=
		\begin{bmatrix}
			0 
			&
			\rho
			&
			1 - \rho^k
			\\
			\rho^k
			&
			0 
			&
			2\rho - \sqrt{2} \rho^{k+1}
