	It suffices to prove~\eqref{eq:cert}; we prove this by induction. The base case $n=1$ is Example~\ref{ex:n=1}. The inductive step is Theorem~\ref{thm:cert}. 
\end{proof}

\begin{lemma}[Multipliers involving $x^*$]\label{lem:opt} 
