\begin{proof}[Proof of Lemma~\ref{lem:succinct}]
	\underline{Gluing component.} 
	Recall that $h_{2n+1} = [h_n, \alpha_n, h_n]$ by the recursive construction~\eqref{eq:steps-recursive} of the Silver Stepsize Schedule. Thus, since $\sig$ certifies the $n$-step rate, we have
	\begin{align*}
		\sum_{i \neq j \in \{0, \dots, n,*\}} \sig_{ij} P_{ij} 
		&=
		\|x_0\|^2 - \|x_n - c_k g_n\|^2
		\\ 
		\sum_{i \neq j \in \{n+1, \dots, 2n,*\}} \sig_{ij} P_{ij} 
		&=
		\|x_{n+1}\|^2 - \|x_{2n+1} - c_k g_{2n+1}\|^2
	\end{align*}
	By definition, $\sum_{ij} \Theta_{ij} P_{ij}$ is the former plus $(1 + 2\rho)$ times the latter. 
	Thus the gluing error $\|x_0\|^2 - \|x_{2n+1} - c_{k+1} g_{2n+1}\|^2 - \sum_{ij} \Theta_{ij} P_{ij}$ is equal to
	\begin{align*}
		(1+2\rho) \|x_{2n+1} - c_k g_{2n+1}\|^2 - \|x_{2n+1} - c_{k+1} g_{2n+1}\|^2 + \|x_n - c_k g_n\|^2 - (1 + 2\rho) \|x_{n+1}\|^2
	\end{align*}
	The key point is that after 
	expanding $x_{n+1} = x_n - \alpha_n g_n$, this is a quadratic form in only the $4$ variables $x_n, g_n, x_{2n+1},g_{2n+1}$. Collecting terms, substituting $c_k = \tfrac{1}{2r_k}$, and using the definition of the Silver Stepsize $\alpha_n = 1 + \rho^{k-1}$ yields $\langle E, vv^T \rangle$, as desired.

	\par \underline{Sparse component.} Expand the definition of the co-coercivity and collect terms. Note also that this equals the matrix $S$ in Part~I~\citep{alt23hedging1}, in the limit that the strong convexity tends to $0$.

	\par \underline{Low-rank component.}  Expanding the co-coercivities, using the identity $x_{2n+1} - x_{n+1}= - \sum_{t=n+1}^{2n} \alpha_t g_t$ by definition of GD, and using the identity $\sum_{t=n+1}^{2n} \alpha_t = \sum_{t=0}^{n-1} \alpha_t = \rho^k - 1$ from Lemma~\ref{lem:sum-steps}, 
	\begin{align*}
		\sum_{t=n+1}^{2n} \Big( \Xi_{n,t} P_{n,t} - \Xi_{*,t} P_{*,t} \Big)
		=
		\rho \sum_{t=n+1}^{2n} \alpha_t \Big(
		2 \langle g_t, g_n - x_n \rangle - \|g_n\|^2
		\Big)
		=
		2\rho \langle x_{2n+1} - x_{n+1}, x_n - g_n \rangle - \rho(\rho^k - 1 ) \|g_n\|^2 \,.
	\end{align*}
	An identical calculation yields
	\begin{align*}
		\sum_{t=n+1}^{2n} \Big( \Xi_{2n+1,t} P_{2n+1,t} - \Xi_{*,t} P_{*,t} \Big)
		&=
		2\rho \langle x_{2n+1} - x_{n+1}, x_{2n+1} - g_{2n+1} \rangle - \rho(\rho^k - 1 ) \|g_{2n+1}\|^2 \,.
	\end{align*}
	Now sum these two displays, use the definition of GD to expand $x_{n+1} = x_n - \alpha_n g_n$, and use the definition of the Silver Stepsize $\alpha_n = 1 + \rho^{k-1}$. This gives $\langle L, vv^T \rangle$, as desired.
\end{proof}

