\begin{theorem}[Main result]\label{thm:main}
	For any horizon $n = 2^k - 1$, any dimension $d$, any $M$-smooth convex function $f : \R^d \to \R$, and any initialization $x_0 \in \R^d$, 
	\begin{align}
		f(x_n) - f^* \leq r_k\, M\|x_0 - x^*\|^2 \,,
	\end{align}
	where $x^*$ denotes any minimizer of $f$, and $x_n$ denotes the output of $n$ steps of GD using the Silver Stepsize Schedule. In particular, in order to achieve error $f(x_n) - f^* \leq \eps$, it suffices to run GD for
	\begin{align*}
		n
		\leq
		\left( \frac{M \|x_0 - x^*\|^2}{2 \eps} \right)^{\log_{\rho} 2} 
		\approx
		\left( \frac{M\|x_0 - x^*\|2}{2 \eps} \right)^{0.7864}
		\;\; \text{iterations}.
	\end{align*}
\end{theorem}

\begin{lemma}[Sum of Silver Stepsizes]\label{lem:sum-steps}
	$\sum_{t=0}^{n-1} \alpha_t = \rho^k - 1$ for any $k \in \N$. 
\end{lemma}

\begin{proof}
	The base case $k=1$ is trivial. The inductive step follows from the recursion~\eqref{eq:steps-recursive}.
\end{proof}

\begin{theorem}[Recursive gluing]\label{thm:cert}
	Let $n = 2^k-1$. Suppose $\{\sig_{ij}\}_{i,j \in \{0,\dots,n,*\}} $ satisfies $*$-sparsity and certifies the $n$-step rate, i.e.,
	\begin{align}
		\sum_{i \neq j \in \{0, \dots, n,*\}} \sig_{ij} Q_{ij} 
		=
		\|x_0 - x^*\|^2 - \|x_n - c_k g_n - x^*\|^2  + \frac{f^* - f_n}{r_k}\ .
		\label{eq:cert:n}
	\end{align}
	Then there exists $\{\lam_{ij}\}_{i, j \in \{0,\dots,2n+1,*\}}$ that satisfies $*$-sparsity and certifies the $2n+1$-step rate, i.e.,
	\begin{align}
		\sum_{i \neq j \in \{0, \dots, 2n+1,*\}} \lam_{ij} Q_{ij} 
		=
		\|x_0 - x^*\|^2 - \|x_{2n+1} - c_{k+1} g_{2n+1} - x^*\|^2 + \frac{f^* - f_{2n+1}}{r_{k+1}}\ .
		\label{eq:cert:2n+1}
	\end{align}
	Moreover, this certificate is explicitly given by
	\begin{align}
		\lam_{ij} = \underbrace{\Theta_{ij}}_{\text{gluing}}
		+
		\underbrace{\Xi_{ij}}_{\text{rank-one correction}}
		+
		\underbrace{\Delta_{ij}}_{\text{sparse correction}}
		\label{eq:lambda}
	\end{align}
	The ``gluing component'' $\Theta$ is defined as 
	\begin{align}
		\Theta_{ij} := \underbrace{\sig_{i,j} \cdot \mathds{1}_{i,j \in \{0,\dots,n,*\}}}_{\text{recurrence for first $n$ steps}}
		\;\;+\;\;
		\underbrace{ (1 + 2\rho)\; \sig_{i-n-1,j-n-1} \cdot \mathds{1}_{i,j \in \{n+1,\dots,2n+1,*\}}}_{\text{recurrence for last $n$ steps}}\,.
		\label{eq:Theta}
	\end{align}
	The ``rank-one correction'' $\Xi$ is zero except the entries $\{\Xi_{ij}\}_{i \in \{n,2n+1,*\},\; j \in \{n+1, \dots, 2n\}}$ which are
	\begin{align}
		\begin{bmatrix}
			\Xi_{n,n+1} & \Xi_{n,n+2} & \cdots & \Xi_{n,2n} \\
			\Xi_{2n+1,n+1} & \Xi_{2n+1,n+2} & \cdots & \Xi_{2n+1,2n} \\
			\Xi_{*,n+1} & \Xi_{*,n+2} & \cdots & \Xi_{*,2n}
		\end{bmatrix}
		:=
		\rho \begin{bmatrix}
			1 \\
			1 \\
			-2
		\end{bmatrix} \begin{bmatrix}
			\alpha_{n+1} & \alpha_{n+2} & \cdots & \alpha_{2n}
		\end{bmatrix}
		\label{eq:Xi}
	\end{align}
	The ``sparse correction'' $\Delta$ is zero except the entries $\{\Delta_{ij}\}_{i \neq j \in \{n,2n+1,*\}}$ which are
	\begin{align}
		\begin{bmatrix}
			\Delta_{n,n}
			&
			\Delta_{n,2n+1}
			&
			\Delta_{n,*} 
			\\
			\Delta_{2n+1,n}
			&
			\Delta_{2n+1,2n+1} 
			&
			\Delta_{2n+1,*} 
			\\
			\Delta_{*,n}
			&
			\Delta_{*,2n+1} 
			&
			\Delta_{*,*}
		\end{bmatrix}
		:=
		\begin{bmatrix}
			0 
			&
			\rho
			&
			1 - \rho^k
			\\
			\rho^k
			&
			0 
			&
			2\rho - \sqrt{2} \rho^{k+1}
			\\
			1 + \rho^{k-1} - \frac{1}{2r_k}
			&
			\frac{1}{2r_{k+1}} - \frac{1+2\rho}{2r_k}
			&
			0
		\end{bmatrix}
		\label{eq:Del}
	\end{align}
\end{theorem}

