\begin{lemma}[Multipliers involving $x^*$]\label{lem:opt} 
	$\sig_{n*} = \rho^k - 1$, $\sig_{*n} = \frac{1}{2r_k}$, and $\sig_{*t} = \alpha_t$ for $t \in \{0,\dots,n-1\}$. 
\end{lemma}

\begin{proof}
	Expand both sides of the identity~\eqref{eq:cert:n} using the $*$-sparsity assumption, the definition of the co-coercivities, and the definition of GD, i.e., $x_t = x_0 - \sum_{s=0}^{t-1} \alpha_s g_s$. Matching coefficients for the $\langle x_0, g_t \rangle$ terms yields the claimed formulas for $\sig_{*t}$. Matching coefficients for the $f^*$ term gives the identity $\sig_{n*} = \sum_{j=0}^n \sig_{*j}-  \tfrac{1}{2r_k}$. This equals $\rho^k - 1$ by Lemma~\ref{lem:sum-steps}. 
\end{proof}

\begin{lemma}[Succinct linear forms]\label{lem:succinct-linear}
	Let $u := [f_n, f_{2n+1}, f^*]^T$, and let $e, s, \ell \in \R^3$ be the vectors defined in Appendix~\ref{app:succinct-linear}. 
	\begin{itemize}
		\item \underline{Gluing error.} $\frac{f^* - f_{2n+1}}{r_{k+1}} - \sum_{ij} \Theta_{ij} F_{ij} = \langle e, u \rangle$
		\item \underline{Sparse correction.} $\sum_{ij} \Delta_{ij} F_{ij} = \langle s, u \rangle$
		\item \underline{Rank-one correction.} $\sum_{ij} \Xi_{ij} F_{ij} = \langle \ell, u \rangle$
	\end{itemize}
\end{lemma}

\begin{proof}
	Expand the definition of co-coercivities, simplify the rank-one correction using Lemma~\ref{lem:sum-steps}, and simplify the sparse correction using the Pell recurrence $\rho^{k+1} = 2\rho^k + \rho^{k-1}$.
\end{proof}

\begin{lemma}[Succinct quadratic forms]\label{lem:succinct} Let $v := [x_n,g_n,x_{2n+1},g_{2n+1}]^T$, and let $E$, $S$, $L$ be the $4 \times 4$ matrices defined in Appendix~\ref{app:succinct}.
	\begin{itemize}
		\item \underline{Gluing error.} 
		$\|x_0\|^2 - \|x_{2n+1} - c_{k+1} g_{2n+1}\|^2
		- \sum_{ij} \Theta_{ij} P_{ij} = \langle E, vv^T \rangle$
		\item \underline{Sparse correction.} $\sum_{ij} \Delta_{ij} P_{ij} = \langle S, vv^T \rangle$
		\item \underline{Rank-one correction.} $\sum_{ij} \Xi_{ij} P_{ij} = \langle L, vv^T \rangle$
	\end{itemize}
\end{lemma}

\begin{proof}
	Deferred to Appendix~\ref{app:succinct} for brevity.
\end{proof}

\begin{proof}[Proof of Lemma~\ref{lem:succinct}]
	\underline{Gluing component.} 
	Recall that $h_{2n+1} = [h_n, \alpha_n, h_n]$ by the recursive construction~\eqref{eq:steps-recursive} of the Silver Stepsize Schedule. Thus, since $\sig$ certifies the $n$-step rate, we have
	\begin{align*}
		\sum_{i \neq j \in \{0, \dots, n,*\}} \sig_{ij} P_{ij} 
		&=
		\|x_0\|^2 - \|x_n - c_k g_n\|^2
		\\ 
		\sum_{i \neq j \in \{n+1, \dots, 2n,*\}} \sig_{ij} P_{ij} 
		&=
		\|x_{n+1}\|^2 - \|x_{2n+1} - c_k g_{2n+1}\|^2
	\end{align*}
	By definition, $\sum_{ij} \Theta_{ij} P_{ij}$ is the former plus $(1 + 2\rho)$ times the latter. 
	Thus the gluing error $\|x_0\|^2 - \|x_{2n+1} - c_{k+1} g_{2n+1}\|^2 - \sum_{ij} \Theta_{ij} P_{ij}$ is equal to
	\begin{align*}
		(1+2\rho) \|x_{2n+1} - c_k g_{2n+1}\|^2 - \|x_{2n+1} - c_{k+1} g_{2n+1}\|^2 + \|x_n - c_k g_n\|^2 - (1 + 2\rho) \|x_{n+1}\|^2
	\end{align*}
	The key point is that after 
	expanding $x_{n+1} = x_n - \alpha_n g_n$, this is a quadratic form in only the $4$ variables $x_n, g_n, x_{2n+1},g_{2n+1}$. Collecting terms, substituting $c_k = \tfrac{1}{2r_k}$, and using the definition of the Silver Stepsize $\alpha_n = 1 + \rho^{k-1}$ yields $\langle E, vv^T \rangle$, as desired.

	\par \underline{Sparse component.} Expand the definition of the co-coercivity and collect terms. Note also that this equals the matrix $S$ in Part~I~\citep{alt23hedging1}, in the limit that the strong convexity tends to $0$.

	\par \underline{Low-rank component.}  Expanding the co-coercivities, using the identity $x_{2n+1} - x_{n+1}= - \sum_{t=n+1}^{2n} \alpha_t g_t$ by definition of GD, and using the identity $\sum_{t=n+1}^{2n} \alpha_t = \sum_{t=0}^{n-1} \alpha_t = \rho^k - 1$ from Lemma~\ref{lem:sum-steps}, 
	\begin{align*}
		\sum_{t=n+1}^{2n} \Big( \Xi_{n,t} P_{n,t} - \Xi_{*,t} P_{*,t} \Big)
		=
		\rho \sum_{t=n+1}^{2n} \alpha_t \Big(
		2 \langle g_t, g_n - x_n \rangle - \|g_n\|^2
		\Big)
		=
		2\rho \langle x_{2n+1} - x_{n+1}, x_n - g_n \rangle - \rho(\rho^k - 1 ) \|g_n\|^2 \,.
	\end{align*}
	An identical calculation yields
	\begin{align*}
		\sum_{t=n+1}^{2n} \Big( \Xi_{2n+1,t} P_{2n+1,t} - \Xi_{*,t} P_{*,t} \Big)
		&=
		2\rho \langle x_{2n+1} - x_{n+1}, x_{2n+1} - g_{2n+1} \rangle - \rho(\rho^k - 1 ) \|g_{2n+1}\|^2 \,.
	\end{align*}
	Now sum these two displays, use the definition of GD to expand $x_{n+1} = x_n - \alpha_n g_n$, and use the definition of the Silver Stepsize $\alpha_n = 1 + \rho^{k-1}$. This gives $\langle L, vv^T \rangle$, as desired.
\end{proof}

\underline{Gluing component.} 
Recall that $h_{2n+1} = [h_n, \alpha_n, h_n]$ by the recursive construction~\eqref{eq:steps-recursive} of the Silver Stepsize Schedule. Thus, since $\sig$ certifies the $n$-step rate, we have
\begin{align*}
	\sum_{i \neq j \in \{0, \dots, n,*\}} \sig_{ij} P_{ij} 
	&=
	\|x_0\|^2 - \|x_n - c_k g_n\|^2
	\\ 
	\sum_{i \neq j \in \{n+1, \dots, 2n,*\}} \sig_{ij} P_{ij} 
	&=
	\|x_{n+1}\|^2 - \|x_{2n+1} - c_k g_{2n+1}\|^2
\end{align*}

An identical calculation yields
\begin{align*}
	\sum_{t=n+1}^{2n} \Big( \Xi_{2n+1,t} P_{2n+1,t} - \Xi_{*,t} P_{*,t} \Big)
	&=
	2\rho \langle x_{2n+1} - x_{n+1}, x_{2n+1} - g_{2n+1} \rangle - \rho(\rho^k - 1 ) \|g_{2n+1}\|^2 \,.
\end{align*}

The matrices in Lemma~\ref{lem:succinct} are defined as follows. For brevity, we write $\sim$ for the entries below the diagonal since these coefficient matrices are symmetric.
